settings.custom_css:
#bt_pulse {-webkit-animation: pulse 1.0s infinite;}

#bt_pulse:hover {-webkit-animation: none;}

@-webkit-keyframes pulse {0% {@include transform(scale(.9)); } 70% {@include transform(scale(1));
    box-shadow: 0 0 0 50px rgba(#5a99d4, 0);} 100% {@include transform(scale(.9)); box-shadow: 0 0 0 0 rgba(#5a99d4, 0);}}

.myPricing{
        --text: 'MAIS VENDIDO!';
        --first-color: #FF3431;
        --second-color: #B10F2E;

        position: relative;
    }
    .myPricing .myRibbon{
        position: absolute;
        top: -14px;
        right: -14px;
        width: 150px;
        height: 150px;
        display: flex;
        justify-content: center;
        align-items: center;
        overflow: hidden;
        z-index: 1
    }
    .myPricing .myRibbon::before{
        content: var(--text);
        position: absolute;
        width: 150%;
        height: 40px;
        background: var(--first-color);
        transform: rotate(45deg) translateY(-20px);
        display: flex;
        justify-content: center;
        align-items: center;
        font-size: 14px;
        font-weight: 600;
        color: #fff;
        letter-spacing: 0.05em;
        box-shadow: 0 5px 10px rgba(0,0,0,0.1);
        font-family: sora;
        font-weight: 700;
    }
    .myPricing .myRibbon::after{
        content: '';
        position: absolute;
        bottom: 0;
        right: 0;
        width: 10px;
        height: 10px;
        background: var(--second-color);
        z-index: -1;
        box-shadow: -140px -140px var(--second-color);
    }

